import sys

class Node:
    __slots__ = ('value', 'prev', 'next')
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    head = None
    tail = None
    for line in input[1:n+1]:
        parts = line.strip().split()
        if parts[0] == 'insert':
            x = int(parts[1])
            new_node = Node(x)
            new_node.next = head
            if head:
                head.prev = new_node
            head = new_node
            if not tail:
                tail = new_node
        elif parts[0] == 'delete':
            x = int(parts[1])
            current = head
            while current is not None:
                if current.value == x:
                    break
                current = current.next
            if current is not None:
                prev_node = current.prev
                next_node = current.next
                if prev_node:
                    prev_node.next = next_node
                else:
                    head = next_node
                if next_node:
                    next_node.prev = prev_node
                else:
                    tail = prev_node
        elif parts[0] == 'deleteFirst':
            if head:
                if head == tail:
                    head = tail = None
                else:
                    new_head = head.next
                    new_head.prev = None
                    head = new_head
        elif parts[0] == 'deleteLast':
            if tail:
                if head == tail:
                    head = tail = None
                else:
                    new_tail = tail.prev
                    new_tail.next = None
                    tail = new_tail
    result = []
    current = head
    while current:
        result.append(str(current.value))
        current = current.next
    print(' '.join(result))

